#include <vector>
#include <CGAL/Exact_predicates_inexact_constructions_kernel.h>

typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
typedef K::Point_2 Point_2;

bool is_polygon_convex(const std::vector<Point_2>& polygon) {
    const int n = polygon.size();
    if (n < 3) return false;
    if (n == 3) return true;

    CGAL::Orientation prev_orientation = CGAL::COLLINEAR;
    for (int i = 0; i < n; ++i) {
        const Point_2& p = polygon[i];
        const Point_2& q = polygon[(i+1) % n];
        const Point_2& r = polygon[(i+2) % n];

        CGAL::Orientation curr_orientation = CGAL::orientation(p, q, r);
        if (curr_orientation == CGAL::COLLINEAR) {
            continue;
        }
        if (prev_orientation == CGAL::COLLINEAR) {
            prev_orientation = curr_orientation;
            continue;
        }
        if (curr_orientation != prev_orientation) {
            return false;
        }
    }
    return prev_orientation != CGAL::COLLINEAR;
}

